from pathlib import Path
import json,zipfile
root=Path(__file__).resolve().parents[2]/'artifacts/flags-oct19/store-10'
langs=json.loads((Path(__file__).parent/'copy.json').read_text())
for lang in langs:
 with zipfile.ZipFile(root/f'Flags-{lang}-iPhone-iPad.zip','w',zipfile.ZIP_DEFLATED,compresslevel=1) as z:
  for fmt in ['iphone','ipad']:
   files=list((root/lang/fmt).glob('*.png'));assert len(files)==10,(lang,fmt,len(files))
   for p in files:z.write(p,f'{fmt}/{p.name}')
(root/'index.html').write_text('''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flags — 10 рекламных экранов</title><style>body{margin:0;background:#091827;color:#eef9ff;font:16px system-ui}header{padding:32px;position:sticky;top:0;background:#091827ed;z-index:1}h1{margin:0 0 14px;font-size:26px}select,a{padding:10px;border-radius:10px;margin-right:12px}a{color:#6af0d9}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:24px;padding:20px 32px}img{width:100%;border-radius:14px}figure{margin:0}figcaption{padding:8px;color:#abbfcd}p{color:#b9ccd9}</style><header><h1>World Arena Flags · 10 экранов × 2 устройства × 8 языков</h1><p>Настоящие экраны приложения. Откройте слайд для просмотра в полном размере.</p><select id="lang"><option value="ru">Русский</option><option value="uk">Українська</option><option value="en">English</option><option value="de">Deutsch</option><option value="fr">Français</option><option value="es">Español</option><option value="it">Italiano</option><option value="pt-BR">Português (Brasil)</option></select><select id="format"><option value="iphone">iPhone · 1320 × 2868</option><option value="ipad">iPad · 2064 × 2752</option></select><a id="zip">Скачать 20 экранов ZIP</a></header><main id="slides"></main><script>const l=document.querySelector('#lang'),f=document.querySelector('#format');function draw(){document.querySelector('#zip').href='Flags-'+l.value+'-iPhone-iPad.zip';document.querySelector('#slides').innerHTML=Array.from({length:10},(_,i)=>{let n=String(i+1).padStart(2,'0'),p=l.value+'/'+f.value+'/'+n+'.png';return '<figure><a href="'+p+'" target="_blank"><img loading="lazy" src="'+p+'"></a><figcaption>'+n+' / 10</figcaption></figure>'}).join('');history.replaceState(null,'','?lang='+l.value+'&device='+f.value)}let q=new URLSearchParams(location.search);l.value=q.get('lang')||'ru';f.value=q.get('device')||'iphone';l.onchange=f.onchange=draw;draw()</script>''')
print('Gallery and eight ZIP archives ready')
